-- Everlake world import, slice 2: loot (drops live Forever shows that the world's loot tables lack)
-- 2026_11_08_02_world_everlake_import_slice2.sql: generated by tools/forever-data in wow-project-everlake from public WoW Forever data.
-- Sources (pins): allthethings 1528abd8252b427ad94a, eg-link 45f58b070b84501f8001, forever-db b183370ed40c718ffada, foreverdb-net 2026-11-08.816c8f61, item-history 8672fdc896ead1073a49, questiedb aa1d7e7294596cf50a6f, wago 1.60.1.70862, wowhead 2026-11-08, wowhead-tooltips parts/2026-11-08T050
-- Written against the fork world forever-tdb-2026-10-14+updates@2ae1313e9f.
-- GPL-3.0: made from GPL-3.0 sources (forever-db's tables, QuestieDB's QuestieTrace corrections) and CC BY 4.0 data from EG Link (Data from Efficient Games, https://efficient.games). Game names belong to Blizzard Entertainment.
-- Never edit this file once it is deployed (the updater would run it and every later custom file again):
-- a later fix is a new file. Running it again changes nothing: see docs/forever-import.md.

CREATE TABLE IF NOT EXISTS `everlake_import_rows` (
  `tbl` varchar(64) NOT NULL COMMENT 'world table of the row',
  `k1` bigint NOT NULL COMMENT 'the row''s key, in the table''s primary key order',
  `k2` bigint NOT NULL DEFAULT '0',
  `k3` bigint NOT NULL DEFAULT '0',
  `k4` bigint NOT NULL DEFAULT '0',
  `file` varchar(200) NOT NULL COMMENT 'the update file that added the row',
  `note` varchar(255) NOT NULL DEFAULT '' COMMENT 'the sources that gave it',
  PRIMARY KEY (`tbl`, `k1`, `k2`, `k3`, `k4`),
  KEY `file` (`file`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Rows the Everlake world import added (docs/forever-import.md)';

-- creature_loot_template: drops the creature's loot table lacks (not where the item drops through one of its reference lists, while a creature still uses the table, and never again once added: a row the fork removes stays removed)
DROP TEMPORARY TABLE IF EXISTS `everlake_import_stage`;
CREATE TEMPORARY TABLE `everlake_import_stage` (`Entry` int unsigned NOT NULL, `ItemType` tinyint NOT NULL, `Item` int unsigned NOT NULL, `Chance` float NOT NULL, `QuestRequired` tinyint(1) NOT NULL, `LootMode` smallint unsigned NOT NULL, `GroupId` tinyint unsigned NOT NULL, `MinCount` tinyint unsigned NOT NULL, `MaxCount` tinyint unsigned NOT NULL, `Comment` varchar(255), `note` varchar(255) NOT NULL, `missing` tinyint NOT NULL DEFAULT '0', PRIMARY KEY (`Entry`, `ItemType`, `Item`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
UPDATE `everlake_import_stage` s SET s.`missing` = 1 WHERE NOT EXISTS (SELECT 1 FROM `creature_loot_template` t WHERE t.`Entry` = s.`Entry` AND t.`ItemType` = s.`ItemType` AND t.`Item` = s.`Item`) AND NOT EXISTS (SELECT 1 FROM `everlake_import_rows` r WHERE r.`tbl` = 'creature_loot_template' AND r.`k1` = s.`Entry` AND r.`k2` = s.`ItemType` AND r.`k3` = s.`Item`) AND NOT EXISTS (SELECT 1 FROM `creature_loot_template` t JOIN `reference_loot_template` x ON x.`Entry` = t.`Item` WHERE t.`Entry` = s.`Entry` AND t.`ItemType` = 1 AND x.`ItemType` = 0 AND x.`Item` = s.`Item`) AND NOT EXISTS (SELECT 1 FROM `creature_loot_template` t JOIN `reference_loot_template` x ON x.`Entry` = t.`Item` JOIN `reference_loot_template` y ON y.`Entry` = x.`Item` WHERE t.`Entry` = s.`Entry` AND t.`ItemType` = 1 AND x.`ItemType` = 1 AND y.`ItemType` = 0 AND y.`Item` = s.`Item`) AND EXISTS (SELECT 1 FROM `creature_template_difficulty` d WHERE d.`LootID` = s.`Entry`);
DROP TEMPORARY TABLE `everlake_import_stage`;

